  "文件归档请使用 npm run backup 完整备份；JSON 导出不包含文件原件和转写。": "Use npm run backup for complete file archives. JSON exports exclude file originals and transcripts.",
  "原始资料已删除或到期，这条历史回答已清除。你可以继续提问，重新检索现有资料。": "Original material was deleted or expired, so this historical answer was cleared. Ask again to search available material.",
  "{0}\n\n#Mote · 由 Mote 创建\n{1}": "{0}\n\n#Mote · Created by Mote\n{1}",
