  "已保存设置发生变化，页面已更新；请检查后重新保存": "Saved settings changed; page updated. Review and save again.",
  "设置保存与恢复均未持久完成，采集已停止；请检查存储空间并重试": "Neither saving nor recovery could persist settings. Collection stopped; check storage and retry.",
  "待同步资料属于原节点，请先同步到原节点；清空连接不会解除资料绑定": "Pending data belongs to the original node. Sync there first; clearing the connection does not remove its binding.",
