  "构建与运行环境": "Build and runtime environment",
  "环境：{0} · {1}\n私有数据目录：{2}": "Environment: {0} · {1}\nPrivate data directory: {2}",
  "开发版与日常 Mote 独立安装，权限、设备 ID、令牌、草稿、队列和模型互不共享。默认测试端口 47842；模拟器使用 adb reverse tcp:47842 tcp:47842。": "Development and daily Mote install separately. Permissions, device IDs, tokens, drafts, queues, and models are isolated. Default test port is 47842; emulators use adb reverse tcp:47842 tcp:47842.",
  "Mote · 让经历留有线索": "Mote · Trace your experiences",
