  "屏幕采集权限说明": "About screen capture permission",
  "\n\n继续后请在系统设置中选择 Mote 屏幕采集。启用服务本身不会开始截图，仍需回到此处点击开始。": "\n\nContinue to system settings and select Mote Screen Capture. Enabling the service does not start screenshots; return here and tap Start.",
  "打开系统设置": "Open system settings",
  "HyperOS 通知使用权：请按需打开实时、对话、通知、静音类别。旧版曾禁用这些类别；更新后若仍是灰色，可关闭再重新授予通知使用权。类别和应用级开关会影响可接收的事件。": "For HyperOS notification access, enable real-time, conversation, notification, and silent categories as needed. Older versions disabled them. If still grey after updating, revoke and grant access again. Category and app switches affect received events.",
  "电池优化设置": "Battery optimization settings",
  "应用详情 / 受限制设置": "App details / Restricted settings",
  "小米 / HyperOS：在系统应用设置中允许 Mote 自启动，将省电策略设为无限制，并允许通知；可在最近任务中锁定应用。菜单随系统版本变化。若侧载 APK 的无障碍开关受限，请在应用详情的菜单中检查“允许受限制的设置”。这些设置不能保证系统永不终止采集。": "Xiaomi / HyperOS: allow autostart, unrestricted battery use, and notifications. You can lock the app in recent tasks. Menus vary by OS version. If sideloaded accessibility access is restricted, check Allow restricted settings in App details. These settings cannot guarantee uninterrupted collection.",
