  "两张图片按原图尺度对齐；滚动任一画面可同步查看细节。质量参数不是文件压缩百分比。": "Both images align at their original scale; scrolling either view synchronizes the details. Quality is not a file-size reduction percentage.",
  "高级设置": "Advanced settings",
  "设备与手动连接": "Device and manual connection",
  "已有节点地址与访问令牌时，也可以手动配置。": "You can also configure an existing node address and access token manually.",
  "用于在中央区分记录来源。": "Identifies this device's records at the central node.",
  "中央地址": "Central node address",
  "留空可仅在本机采集；远程地址使用 HTTPS。": "Leave blank for local-only capture; remote addresses require HTTPS.",
  "访问令牌": "Access token",
  "使用系统密钥存储加密；不会展示已有令牌。": "Encrypted using system credential storage; existing tokens are never displayed.",
  "将本机积存记录同步到这个节点": "Sync accumulated local records to this node",
  "已绑定节点的待传记录始终属于原节点。清空地址不会解除绑定；迁移前请先完成上传或导出并移走旧队列。": "Pending records bound to a node always belong to it. Clearing the address does not unbind them. Before migrating, finish uploading or export and remove the old queue.",
  "本地采集和上传独立运行": "Local capture and uploads run independently",
  "01 · 先保存": "01 · Save first",
  "02 · 按策略发送": "02 · Send under your policy",
  "停止采集不会停止已有记录的同步。应用运行时执行计划；电脑休眠或应用退出时延后。": "Stopping capture does not stop syncing existing records. Schedules run while the app is active; sleep or quitting delays them.",
  "管理连接地址 →": "Manage connection address →",
  "仅采集主屏幕。锁屏和休眠时始终暂停。": "Only the main display is captured. Capture always pauses while locked or asleep.",
  "采样间隔（秒）": "Sampling interval (seconds)",
  "相同画面复用本地图像，保留每次采样记录。": "Identical screens reuse local images while retaining every sample record.",
  "连续空闲后暂停（秒）": "Pause after idle time (seconds)",
  "默认 300；设为 0 可关闭空闲检测。": "Default 300; set to 0 to disable idle detection.",
