  "让 Mote 按照你的设备使用方式运行。": "Make Mote fit how you use your device.",
  "登录时打开 Mote": "Open Mote at login",
  "应用启动后保持停止状态，需手动开始采集；已有队列按上传策略处理。": "Capture stays stopped at launch until you start it manually; existing queues follow the upload policy.",
  "使用电池时暂停采集": "Pause capture on battery",
