  "屏幕示意 · 遮挡区域不会保存": "Screen diagram · Masked regions are not saved",
  "遮挡相对主屏幕左上角定位，保存和文字识别之前生效。添加后请根据实际屏幕布局调整范围。": "Masks are relative to the main display's top-left corner and apply before saving and OCR. Adjust them to match your screen layout.",
  "遮挡区域 JSON": "Mask regions JSON",
  "x / y / width / height 使用 0–1 的比例。编辑后离开输入框即可更新示意。": "x / y / width / height use ratios from 0 to 1. Leave the field after editing to update the diagram.",
  "设备元数据": "Device metadata",
  "选择是否附带设备运行环境。": "Choose whether to include device environment details.",
  "上传设备与采样元数据": "Upload device and sample metadata",
  "关闭后仍保留基本应用与时间记录；文件来源的时间元数据不受此开关影响。": "Basic app and time records remain when disabled; file-source timestamps are unaffected.",
  "可能包含哪些数据": "What may be included",
  "可包含系统版本、硬件型号、语言时区、电量、温度级别、空闲时间、锁屏状态、可用空间，以及完整内容截图参数；不包含序列号、SSID 或定位。平台未提供的值留空。": "May include OS version, hardware model, language and timezone, battery, thermal level, idle time, lock state, free space, and full-content screenshot parameters. Serial numbers, SSIDs, and location are excluded. Unavailable values are omitted.",
  "最大生成 token": "Maximum output tokens",
  "图像与资源优化": "Image and resource optimization",
  "打开图片压缩预览 →": "Open image compression preview →",
  "在存储占用和文字清晰度之间调整。": "Balance storage use and text clarity.",
  "较低质量减少存储，可能影响小字识别。": "Lower quality saves space but may impair recognition of small text.",
  "本机诊断": "Local diagnostics",
  "不记录截图、OCR、记录、审查策略、节点地址或令牌。电量是整台设备的变化，不是 Mote 的耗电归因。": "Does not record screenshots, OCR, quick notes, review policies, node addresses, or tokens. Battery changes reflect the whole device, not Mote's power consumption.",
