  "更新来源与安装说明": "Update source and installation",
  "更新来自 GitHub utopiafar/mote，只接受内置发布公钥验证通过的安装包。": "Updates come from GitHub utopiafar/mote. Only installers verified by the built-in release public key are accepted.",
  "安装前请保存尚未提交的设置。记录草稿会先保存；所有 profile、Keychain、草稿、队列与模型目录保留。请先退出同一 App 的其他 profile。ad-hoc 签名更新后，macOS 可能再次要求授权；不会重置你的资料。安装目录不可写时可使用 Finder 手动替换 App。": "Save unsubmitted settings before installing. Quick-note drafts are saved first; all profiles, Keychain entries, drafts, queues, and model directories are retained. Quit other profiles of this app first. macOS may request permissions again after an ad-hoc signed update; your data is not reset. If the installation directory is not writable, replace the app manually in Finder.",
  "关闭窗口后 Mote 仍会驻留菜单栏；如需完全退出，请使用菜单栏中的退出操作。": "Mote stays in the menu bar after the window closes. Use Quit in the menu bar to exit completely.",
