  "请先完成模型配置。": "Complete the model configuration first.",
  "请求等待超时，请查看任务状态。": "The request timed out. Check the task status.",
  "运行已中断，请查看历史结果后重新发起。": "The run was interrupted. Review its history before starting a new run.",
  "连接暂时中断，请检查网络。": "The connection was interrupted. Check the network.",
  "先检索 memories 的精选记忆概览，再按需展开相关记忆、observation 和 segments。Memory 未命中不代表原始事件不存在；参考整理覆盖信息，用 changes 的 overview 或全文检索发现尚未整理的增量。只对有意义的发现选择性读取原始证据，核实最终报告的事实、数字、归属和时间。不要穷尽读取本窗口全部原文；预算不足时用已有证据生成范围明确的部分报告，说明未覆盖内容。注意迟到上传、修订、人物归属、偏好变化及计划的未知结果。没有支持时明确说明信息不足。不要声称完整回顾了全部历史。按照宿主固定范围检索，允许范围内跨月检索。": "Search the curated memories overview first, then expand relevant memories, observations, and segments as needed. Missing memory does not mean the original event is absent; use organization coverage and the changes overview or full-text search to find unprocessed additions. Read original evidence selectively for meaningful findings to verify facts, numbers, attribution, and times. Do not exhaustively read every original in this window. If the budget is insufficient, produce a clearly scoped partial report from available evidence and state what remains uncovered. Account for late uploads, revisions, attribution, preference changes, and unknown outcomes of plans. State when evidence is insufficient. Do not claim to have reviewed the entire history. Follow the host-defined scope, allowing searches across months within it.",
