  "这是用户主动纠正的版本，原始说明已保留。": "This version was explicitly corrected by the user. The original statement is retained.",
  "已通过独立模型审核和引用校验。": "Passed independent model review and citation checks.",
  "模型未补充不确定性；可查看下方证据核对。": "The model provided no uncertainty details. You can inspect the evidence below.",
  "纠正记忆": "Correct memory",
  "纠正后的内容": "Corrected content",
  "记忆以文本保存，可按需查看概览、内容与边界、原始证据。通过自动审核和证据校验后直接生效，你可以随时纠正或删除。历史资料提取按窗口处理已圈定的积压，每轮窗口上限控制成本。": "Memories are stored as text. View summaries, contents, boundaries and original evidence as needed. They take effect after automatic review and evidence validation, and you can correct or delete them at any time. Historical extraction processes a fixed backlog in windows; the per-round window limit controls cost.",
