  "筛选": "Filter",
  "这些提取门槛与最大等待时间只控制历史资料的窗口处理。已授权且内容就绪的新资料直接进入自动记忆队列，按可用名额持续处理。": "These extraction thresholds and maximum wait apply only to historical processing windows. Newly authorized records with ready content enter the automatic memory queue directly and are processed as capacity becomes available.",
  "持续整理新资料": "Continuously process new records",
  "为新接收的来源资料选择记忆策略。多个策略可共用处理结果；保存设置不会重算历史资料，已有记忆仍保留。": "Choose memory strategies for new source records. Strategies can share processing results; saving does not reprocess history, and existing memories are retained.",
