  "使用投屏模式（只截图，每次需授权）": "Use projection mode (screenshots only; consent required each time)",
  "默认无障碍采集支持页面字段与截图回退。选择投屏会同时改为只截图，锁屏/被杀后必须重新授权。Android 10 截图请选投屏模式。": "Accessibility capture supports page fields and screenshot fallback. Choosing projection also selects screenshots only; consent must be renewed after locking or termination. Use projection for screenshots on Android 10.",
  "本周期累计页面 {0} · 截图 {1} · 应用活动 {2} · 媒体 {3} · 笔记 {4} · 已确认 {5}\n拦截 {6} · 失败 {7} · 重试结果 {8}": "This period: pages {0} · Screenshots {1} · Activity {2} · Media {3} · Notes {4} · Acknowledged {5}\nBlocked {6} · Failed {7} · Retry outcomes {8}",
  "本周期累计页面 {0}    截图 {1}    活动 {2}    媒体 {3}    记录 {4}\n本周期已同步 {5} 条": "This period: pages {0}    Screenshots {1}    Activity {2}    Media {3}    Notes {4}\nSynced this period: {5}",
  "媒体采集可单独开启，在前台、后台和锁屏时观察播放器公开的状态、应用及曲目/章节信息；不录音、不控制播放。普通通知由单独的通知采集开关控制。使用本机页的开始/暂停控制采集。媒体沿用应用隐私规则、电量限制和同步策略；关闭元数据会同时暂停媒体。": "Independently observes public player state, app, and track/chapter details in foreground, background, and lock screen. No audio recording or playback control. Ordinary notifications have a separate switch. Use Start/Pause on Device. App privacy, battery, and sync policies apply; disabling metadata also pauses media.",
  "日常事件": "Daily events",
  "截图和页面采集默认组合": "Screenshot and page capture defaults",
  "截图和页面采集使用独立默认组合；来源覆盖优先。日常事件保留浏览和行动线索，区分计划与完成，并可在对话中按天回顾。": "Screenshots and page captures use separate defaults; source overrides take priority. Daily events preserve browsing and action history, distinguish plans from completion, and can be recalled by day in chat.",
