  "可信插件代码拥有中央宿主权限；访问声明不是沙箱隔离。安装完成后仍需配置、启用与绑定。": "Trusted plugin code has central host privileges; declared access is not sandbox isolation. Installation still requires configuration, enabling, and binding.",
  "正在安装…": "Installing…",
  "安装此版本": "Install this version",
  "更换正文权威时须迁移记忆正文、修正与删除标记，再准备索引。同一正文权威只更换检索时可重建索引。准备完成不会自动生效。": "Changing content authority requires migrating memory content, corrections, and deletion markers before preparing indexes. Replacing retrieval under the same authority may rebuild only indexes. Preparation does not activate a plan automatically.",
  "历史授权范围": "Authorized historical scope",
  "范围必须已获授权；准备不包含未授权历史或暂停期间的新提取。": "The scope must already be authorized. Preparation excludes unauthorized history and new extraction of data from a paused period.",
  "已确认范围。真实接入可能产生模型与 Embedding 费用，费用以实际服务用量为准。": "I have reviewed the scope. Real services may incur model and embedding costs, billed according to actual usage.",
  "生效前会冻结旧方案新增写入，排空并核对尾部任务，验证新绑定；既有查询仍读取固定旧版本。": "Before activation, freeze new writes under the old plan, drain and reconcile tail tasks, and verify the new binding. Existing queries continue reading their pinned old version.",
  "正在登记…": "Registering…",
  "开始准备": "Start preparation",
  "撤销旧任务继续写入的权限，并请求取消运行中的自动记忆任务。外部工作可能无法立刻停止，未确认结果会单独保留。": "Revoke old tasks' write authority and request cancellation of running automatic memory tasks. External work may not stop immediately; unconfirmed results remain tracked separately.",
  "原件、已有记忆和只读查询继续保留；恢复后只处理新资料。": "Originals, existing memories, and read-only queries remain available. Resuming processes only new data.",
  "确认立即停止": "Confirm immediate stop",
  "请求已登记，运行状态以中央返回为准。": "The request has been registered. Runtime state is reported by the central node.",
  "配置实例与资料范围，再单独启用。启用不会自动替换当前记忆方案。": "Configure the instance and data scope, then enable it separately. Enabling does not automatically replace the current memory plan.",
  "实例名称": "Instance name",
  "由中央核验授权范围；填写范围不会授予新的数据权限。": "The central node verifies scope authorization. Entering a scope does not grant new data access.",
  "仅填写服务器保存的凭据引用，不填写凭据本身。": "Enter a reference to credentials stored on the server, never the credentials themselves.",
  "服务器已配置凭据。": "Credentials are configured on the server.",
  "先创建实例，中央返回此插件的配置字段。": "Create an instance first to retrieve the plugin's configuration fields from the central node.",
