  "记忆已禁止使用。": "This Memory is no longer used.",
  "迁移全部 Mote 保留记忆正文及更正/替代状态。外部原生审计历史和引擎图保留在旧实例及运行备份中，不承诺跨引擎迁移。": "Migration includes all Memory bodies retained by Mote and their correction/supersession states. Native provider audit history and engine graphs remain in the old instance and runtime backup; cross-engine migration of them is not guaranteed.",
