  "这项旧任务需要正式资料才能确认归属，不能自动继续。已审核结果保留，可以取消未完成任务。": "This older task needs published material to confirm attribution and cannot continue automatically. Reviewed results are retained. You can cancel the unfinished task.",
  " · 有处理事项需关注": " · Processing needs attention",
  "：已有可用默认时可直接使用；需要设置时，按下面顺序检查。": ": Use an available default directly. If setup is needed, check the following in order.",
