  "按你选择的资料范围回顾经历，梳理项目进展、反复出现的线索与待核对的问题。结论附带原文引用，你可以继续提问或回到证据核对。": "Review experiences within your selected scope, including project progress, recurring evidence and questions to verify. Conclusions include original citations, so you can ask further questions or check the evidence.",
