  "请先选择服务商并填写服务地址；可用模型目录会随后加载。": "Choose a provider and enter its URL first. The available model catalog will then load.",
  "请先在「设置 → 模型与服务 → 模型 Provider」配置服务地址和模型。尚未配置时，模型目录不可读取。": "Configure the service URL and model in Settings → Models & services → Model connection (Provider) first. Until configured, its model catalog cannot be read.",
  "请先在设置 → 模型与服务 → 来源与外部应用中准备 Google OAuth 客户端与回调地址，然后重启节点。": "Prepare the Google OAuth client and callback in Settings → Models & services → Sources and external apps, then restart Central.",
