  "下载中": "Downloading",
  "先安装 Mac 客户端并连接中央，再在客户端打开「来源 → 连接 Coding Agent」，选择本机实际存在的 Claude Code、Codex 或 Kimi 和采集范围，启动同步。这里查看同步状态；本机采集由客户端控制。": "Install the Mac client and connect it to Central. In the client, open Sources → Connect Coding Agent, choose a locally available Claude Code, Codex or Kimi and its capture scope, then start syncing. This page shows sync status; capture is controlled by the native client.",
  "先安装并连接 Mac 客户端，在客户端「来源 → 连接 Coding Agent」选择实际存在的 Agent 与采集范围。这里打开说明和同步状态。": "Install and connect the Mac client, then use Sources → Connect Coding Agent in the client to choose an available Agent and capture scope. This link opens instructions and sync status.",
  "先保存或检查已有模型连接，再检查这项任务对应的模块；回到原任务，按它当前提供的操作继续。": "Save or inspect the model connection first, then check the module used by this task. Return to the original task and continue using its currently available controls.",
  "先从官方发布页安装客户端；采集与隐私范围在本机设置。": "Install the client from the official releases page first. Capture and privacy scope are controlled on the device.",
  "先在中央授权厂商账号，确认所需读取权限，再选择历史范围并启用同步。飞书文档与日历的授权另在自己的页面管理。": "Authorize the provider account on Central first, confirm required read scopes, then select the historical range and enable sync. Feishu documents and calendars have separate authorization settings.",
  "想分析正文时，在可访问原件的客户端保存快照。": "To analyze the body, save a snapshot from a client that can read the original.",
