  "暂时无法读取服务商模型目录。请检查已配置的地址、凭据和服务商支持情况；也可填写模型 ID。": "The provider's model catalog cannot be read right now. Check the saved URL, credentials and provider support, or enter a model ID.",
  "暂时无法读取模型目录。请检查服务地址、凭据和目录支持情况，也可手动填写模型 ID。": "The model catalog cannot be read right now. Check the service URL, credentials and catalog support, or enter a model ID manually.",
  "这里是 Mote 的后台工作：理解资料、导入、整理记忆与生成洞察。手机和电脑的应用使用情况在「资料库 → 应用活动」。": "This shows Mote's background work: interpreting materials, importing, organizing Memory and generating insights. Phone and computer app usage is in Library → App activity.",
