  "授权后，范围内明确的日历写入可自动执行；消息发送仍需逐条确认。更新和取消只作用于 Mote 创建的原事件；完成仅记录在 Mote。不会邀请参与人或扩大目标范围。": "After authorization, calendar writes that are clear and in scope may run automatically; message sends still require confirmation for every message. Updates and cancellations only affect original events created by Mote; completion is recorded only in Mote. Participants are never invited and the target scope is never widened.",
  "先在设备连接日历，或在插件中心安装、检查和启用声明行动能力的官方连接器。安装和升级不会自动授予执行权限。": "First connect a calendar on a device, or install, check and enable an official connector that declares an action capability in Plugin Center. Installing or upgrading never grants execution by itself.",
