  "来源最近一次观察时间不代表设备当前在线。提取、语义理解、向量索引和原件打开分别确认。": "The latest source observation does not mean the device is online now. Extraction, semantic processing, vector indexing and original access are confirmed separately.",
  "快照原件未保留；已提取正文仍按当前覆盖和读取权限提供。": "The snapshot original is not retained. Extracted text remains available according to current coverage and read permissions.",
