  "排队等待回答": "Queued for an answer",
  "服务端按当前模型窗口和完整请求预算计算历史目标；这里只保存比例与窗口偏好，不在浏览器中估算。": "The server computes the history target from the current model window and the complete request budget. This form only saves ratio and window preferences; the browser does not estimate them.",
  "模型窗口": "Model window",
  "窗口大小（tokens）": "Window size (tokens)",
  "缺少可信能力信息时使用保守窗口。历史目标是比例与请求预算的较小值，由服务端在每次请求时计算。": "A conservative window is used when trusted capability information is missing. The history target is the smaller of the ratio and the request budget, computed by the server on each request.",
