  "连接成功只表示可以同步，不代表全库已经理解。": "A successful connection only means syncing is available; it does not mean the whole Library is understood.",
  "这里只决定本次初次认识读取哪些已同步资料，不改变来源授权或保存方式。": "This only chooses which synced materials this first acquaintance reads; it does not change source authorization or retention.",
  "同步、正文提取和语义理解分别计算；连接或提取完成不等于语义理解完成。": "Syncing, text extraction and semantic understanding are counted separately; connection or extraction completion does not mean semantic understanding is complete.",
